Příklad použití komponenty


Je dobré si všimnout, že nastavování vlastnosti s definicí typů filtru je vidět
přímo při zadávání této vlatsnosti        	



// kód vygenerovaný Visual Studiem.Net + nastavení odchycení daných událostí komponenty

private void InitializeComponent()
{ 
	...
	this.m_oFilter.FilterTypes = new string[] {
                        "všechny",
                        "osobní",
                        "veřejné",
                        "AAAAAAAAAAAAAAAA"};
    this.m_oFilter.Location = new System.Drawing.Point(80, 32);
    this.m_oFilter.Name = "gFilter2";
    this.m_oFilter.Size = new System.Drawing.Size(328, 208);
    this.m_oFilter.TabIndex = 2;
    this.m_oFilter.FilterTypeChanged += new System.EventHandler(this.m_oFilter_FilterTypeChanged);
    this.m_oFilter.SelectFilter +=new EventHandler(m_oFilter_SelectFilter);
	...
}

// příklad obsluhy jednotlivých událostí

1. je nutno výběr typu filtrů ošetřit takto

m_oFilter[2].Click +=new EventHandler(Vyber_verejnych);

...
private void Vyber_verejnych(object sender, EventArgs e)
{                    
   // select do příslušné tabulky pro dané hodnoty možných filtrů pro daný typ
   m_oFilter.SetListFilters(pole s klíči hodnot filtrů); 
}//end method
...

2. je nutno výběr již konkrétního filtru ošetřit takto

this.m_oFilter.SelectFilter +=new EventHandler(m_oFilter_SelectFilter);
...
private void m_oFilter_SelectFilter(object sender, EventArgs e)
{
    //načtení klíče vybraného filtru z vlastnosti

    string l_sActual = m_oFilter.ActualFilterName;
}
